1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Calculator</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0; min-height: 100vh; display: grid; place-items: center;
11	    background: #eef0f3; font-family: system-ui, -apple-system, sans-serif;
12	  }
13	  .calc {
14	    width: min(320px, 92vw); padding: 16px; border-radius: 16px;
15	    background: #1f2329; box-shadow: 0 10px 30px rgba(0,0,0,.25);
16	  }
17	  .display {
18	    height: 72px; margin-bottom: 12px; padding: 0 12px; border-radius: 10px;
19	    background: #2c323a; color: #fff; font-size: 2.2rem;
20	    display: flex; align-items: center; justify-content: flex-end;
21	    overflow: hidden; white-space: nowrap;
22	  }
23	  .keys { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; }
24	  button {
25	    height: 60px; border: 0; border-radius: 10px; font-size: 1.3rem;
26	    background: #3a414b; color: #fff; cursor: pointer;
27	  }
28	  button:active { filter: brightness(1.2); }
29	  .op { background: #f59e0b; }
30	  .clear { background: #6b7280; }
31	  .equals { background: #10b981; }
32	  .wide { grid-column: span 2; }
33	</style>
34	</head>
35	<body>
36	<div class="calc">
37	  <div class="display" data-testid="calc-display" data-value="0">0</div>
38	  <div class="keys">
39	    <button class="clear wide" data-testid="key-clear" data-action="clear">AC</button>
40	    <button class="op" data-testid="key-div" data-op="/">÷</button>
41	    <button class="op" data-testid="key-mul" data-op="*">×</button>
42	    <button data-testid="key-7" data-digit="7">7</button>
43	    <button data-testid="key-8" data-digit="8">8</button>
44	    <button data-testid="key-9" data-digit="9">9</button>
45	    <button class="op" data-testid="key-sub" data-op="-">−</button>
46	    <button data-testid="key-4" data-digit="4">4</button>
47	    <button data-testid="key-5" data-digit="5">5</button>
48	    <button data-testid="key-6" data-digit="6">6</button>
49	    <button class="op" data-testid="key-add" data-op="+">+</button>
50	    <button data-testid="key-1" data-digit="1">1</button>
51	    <button data-testid="key-2" data-digit="2">2</button>
52	    <button data-testid="key-3" data-digit="3">3</button>
53	    <button class="equals" data-testid="key-equals" data-action="equals">=</button>
54	    <button class="wide" data-testid="key-0" data-digit="0">0</button>
55	    <button data-testid="key-dot" data-action="dot">.</button>
56	  </div>
57	</div>
58	<script>
59	  // State: acc = stored left operand, op = pending operator,
60	  // entry = digits being typed (string) or null, value = number shown.
61	  var state = { acc: null, op: null, entry: null, value: 0, error: false };
62	
63	  function compute(a, op, b) {
64	    var r;
65	    if (op === '+') r = a + b;
66	    else if (op === '-') r = a - b;
67	    else if (op === '*') r = a * b;
68	    else r = a / b;
69	    if (!isFinite(r)) return NaN;
70	    return parseFloat(r.toPrecision(12));
71	  }
72	
73	  function pressDigit(d) {
74	    if (state.error) clear();
75	    if (state.entry === null || state.entry === '0') state.entry = d;
76	    else state.entry += d;
77	    state.value = Number(state.entry);
78	  }
79	
80	  function pressDot() {
81	    if (state.error) clear();
82	    if (state.entry === null) state.entry = '0';
83	    if (state.entry.indexOf('.') === -1) state.entry += '.';
84	    state.value = Number(state.entry);
85	  }
86	
87	  function resolve() {
88	    if (state.op !== null && state.entry !== null) {
89	      state.value = compute(state.acc, state.op, state.value);
90	      if (isNaN(state.value)) state.error = true;
91	    }
92	  }
93	
94	  // Immediate execution, no precedence: each operator key first finishes the
95	  // waiting operation, strictly left to right, so the display always shows a
96	  // real running result. 2 + 3 × 4 = is 20, not 14.
97	  function pressOp(op) {
98	    if (state.error) return;
99	    resolve();
100	    if (state.error) return;
101	    state.acc = state.value;
102	    state.op = op;
103	    state.entry = null;
104	  }
105	
106	  function pressEquals() {
107	    if (state.error) return;
108	    resolve();
109	    state.acc = null;
110	    state.op = null;
111	    state.entry = null;
112	  }
113	
114	  function clear() {
115	    state = { acc: null, op: null, entry: null, value: 0, error: false };
116	  }
117	
118	  var display = document.querySelector('[data-testid="calc-display"]');
119	
120	  function render() {
121	    display.setAttribute('data-value', String(state.value));
122	    if (state.error) display.textContent = 'Error';
123	    else display.textContent = state.entry !== null ? state.entry : String(state.value);
124	  }
125	
126	  document.querySelector('.keys').addEventListener('click', function (e) {
127	    var b = e.target.closest('button');
128	    if (!b) return;
129	    if (b.dataset.digit !== undefined) pressDigit(b.dataset.digit);
130	    else if (b.dataset.op) pressOp(b.dataset.op);
131	    else if (b.dataset.action === 'dot') pressDot();
132	    else if (b.dataset.action === 'equals') pressEquals();
133	    else if (b.dataset.action === 'clear') clear();
134	    render();
135	  });
136	
137	  render();
138	</script>
139	</body>
140	</html>
